(function () {
window.AINOW = window.AINOW || {};
var __exports = AINOW['data/data-hr'] = AINOW['data/data-hr'] || {};
const hrPrompts = [

    {"id":"hr-1","title":"30-Day Performance Improvement Plan","prompt":"You are an experienced HR Business Partner at a 300-person SaaS company. Draft a 30-day Performance Improvement Plan for a mid-level Customer Success Manager who has missed their quarterly renewal target by 35% for two consecutive quarters, has received three customer escalations in the past 60 days citing unresponsiveness, and was rated 'Below Expectations' in their last performance review. The PIP should include: a factual description of the performance gap without subjective language, 4 specific measurable objectives for the 30-day period with clear success criteria, a weekly check-in structure with the manager, resources and support the company will provide, and a plain-English explanation of outcomes if the plan is not met. Tone: firm, fair, legally careful, and human.","tags":["performance","pip","employee-relations"],"author":"AINOW","created":"2024-02-15T10:00:00Z","featured":true},

    {"id":"hr-2","title":"Bias-Blind Resume Screening Rubric","prompt":"You are a senior talent acquisition specialist designing a structured screening process. Create a detailed resume scoring rubric for a Senior Product Manager role at a B2B fintech company. The rubric must: award points only for demonstrable skills, years of relevant domain experience, and concrete outcomes (not university names, company prestige, or graduation year); include a 1–4 scoring scale for each criterion with behavioral anchors describing what each score looks like; flag which fields reviewers should ignore to reduce affinity bias; and include a box for reviewers to sign confirming they applied the rubric before viewing candidate names. Produce the full rubric table plus a one-page reviewer briefing note.","tags":["hiring","dei","talent-acquisition"],"author":"AINOW","created":"2024-02-15T10:05:00Z","featured":true},

    {"id":"hr-3","title":"Structured Behavioral Interview Guide","prompt":"You are an HR lead building a repeatable hiring process. Create a complete structured behavioral interview guide for hiring a Head of Engineering at a 150-person Series B startup. Include: 6 behavioral questions mapped to the competencies of technical leadership, cross-functional communication, team development, delivery under ambiguity, hiring judgment, and managing technical debt; for each question provide a STAR-format follow-up probe and a 1–4 scoring rubric with specific behavioral indicators at each level; a debrief agenda for the hiring panel; and a calibration note explaining how to resolve disagreement between interviewers. The guide should take a trained interviewer approximately 60 minutes to administer.","tags":["hiring","interviewing","talent-acquisition"],"author":"AINOW","created":"2024-02-15T10:10:00Z","featured":false},

    {"id":"hr-4","title":"Passive Candidate Outreach Sequence","prompt":"You are a senior technical recruiter. Write a three-touch outreach sequence to recruit a Senior Data Scientist currently working at a large e-commerce company who has been publishing papers on recommendation systems and recently spoke at a PyData conference. The role is a Staff Data Scientist position at an early-stage AI company building personalization infrastructure for media streaming. Touch 1 is a LinkedIn message (under 120 words) referencing their conference talk; Touch 2 is a follow-up email sent 5 days later adding a specific detail about the technical problem the team is solving; Touch 3 is a final short message 7 days after that creating a soft close. Each message must feel personal, not templated, and should articulate a genuine reason why this specific person is being contacted. Do not use hollow phrases like 'exciting opportunity' or 'great fit'.","tags":["sourcing","outreach","talent-acquisition"],"author":"AINOW","created":"2024-02-15T10:15:00Z","featured":false},

    {"id":"hr-5","title":"Job Description Bias Audit","prompt":"You are an organizational psychologist specializing in inclusive hiring. Take the following Software Engineer job description and perform a full bias audit. Identify: words or phrases with masculine-coded language (e.g. 'ninja', 'dominate', 'aggressive growth targets') and suggest gender-neutral alternatives; credential requirements that likely function as proxy screens for socioeconomic background (e.g. specific university names, unpaid internship experience); any physical requirements that are not genuinely essential to the role; and any culture-fit language that could screen out neurodiverse candidates. For each issue, explain the mechanism by which it creates bias, then provide a rewritten version of that sentence or phrase. Conclude with an overall bias risk rating of Low, Medium, or High with a one-paragraph justification. Job description to audit: [paste JD here — this tool will analyse whatever you provide]","tags":["dei","hiring","job-descriptions"],"author":"AINOW","created":"2024-02-15T10:20:00Z","featured":false},

    {"id":"hr-6","title":"Offer Letter with Full Compensation Narrative","prompt":"You are a compensation specialist at a venture-backed technology company. Draft a formal offer letter for a candidate accepting a Principal Software Engineer role. The letter should cover: a warm but professional opening from the hiring manager; base salary of $195,000 per year paid bi-weekly; annual performance bonus target of 15% of base, paid in March, subject to company and individual performance; an equity grant of 0.12% of fully diluted shares as ISO stock options, vesting over 4 years with a 1-year cliff, at a strike price to be set at the next 409A valuation; benefits including medical/dental/vision with the company covering 90% of the premium for the employee and 70% for dependents; 20 days PTO plus 11 company holidays; a $3,000 annual learning and development budget; a start date of the first Monday of the following month. Include a plain-English equity explainer paragraph that a non-financial reader can understand. Close with next steps for acceptance.","tags":["compensation","hiring","legal"],"author":"AINOW","created":"2024-02-15T10:25:00Z","featured":false},

    {"id":"hr-7","title":"Employee Value Proposition for Engineers","prompt":"You are a talent brand strategist. Write a compelling, honest Employee Value Proposition targeted specifically at senior software engineers with 8+ years of experience who are choosing between your company and a FAANG offer. Your company is a 200-person climate tech startup building grid optimization software, Series C funded, profitable, with a distributed-first culture and no return-to-office mandate. The EVP must address four dimensions engineers actually care about: technical challenge and stack quality (be specific about the tech, not vague); autonomy and decision-making authority; career trajectory and how fast people grow here compared to larger companies; and compensation philosophy including equity upside narrative. Write in a direct, non-corporate voice. Avoid the words 'passionate', 'fast-paced', 'innovative', and 'rockstar'. The full EVP should be 400–500 words and usable as a careers page hero section.","tags":["employer-branding","talent-acquisition","strategy"],"author":"AINOW","created":"2024-02-15T10:30:00Z","featured":false},

    {"id":"hr-8","title":"Technical Take-Home Assessment Design","prompt":"You are an engineering hiring lead. Design a take-home technical assessment for a Senior Backend Engineer role (Python, distributed systems) that can be completed in 90 minutes by a working professional. The assessment must: test real-world problem-solving in the domain of event-driven architecture, not algorithmic puzzle-solving; include a clear problem brief, a starter repository structure, evaluation criteria visible to the candidate, and submission instructions; specify exactly what reviewers will grade and how (with a scoring rubric); explain to the candidate why this task was chosen and how it relates to actual day-to-day work; and include a follow-up interview agenda (30 minutes) for discussing the solution. Also include a section telling the candidate they can use any resources including AI tools, and explain how the reviewer will distinguish genuine understanding from copied output. Optimize for candidate respect and signal quality.","tags":["hiring","assessment","engineering"],"author":"AINOW","created":"2024-02-15T10:35:00Z","featured":false},

    {"id":"hr-9","title":"Reference Check Conversation Guide","prompt":"You are a senior HR professional. Write a reference check conversation guide for a VP of Sales candidate at a 400-person B2B SaaS company. The guide should include: an opening script for securing candid feedback (explaining confidentiality and the reference's importance); 8 substantive questions that surface information about the candidate's leadership style under pressure, how they handle missed targets, their relationship with the product team, and how they develop junior salespeople; a question specifically designed to surface potential derailers without being leading; a 'would you rehire' question with follow-up probes for hesitation; a closing script; and a reference summary template for documenting what was said. Include coaching notes for the interviewer on how to handle vague or evasive answers. The guide should take 20–25 minutes to administer.","tags":["hiring","vetting","talent-acquisition"],"author":"AINOW","created":"2024-02-15T10:40:00Z","featured":false},

    {"id":"hr-10","title":"Succession Planning Facilitation Guide","prompt":"You are an HR Director running a succession planning session for a 500-person manufacturing company with a leadership team of 12. Create a full facilitation guide for a 3-hour succession planning workshop. Include: a pre-work brief for leaders (to be distributed one week before); a 9-box talent calibration exercise with instructions, scoring criteria, and calibration norms; an identification process for the top 5 mission-critical roles; for each critical role, a structured template capturing the current incumbent's risk level (flight risk, retirement horizon), the names of internal candidates at Ready Now, Ready in 12 Months, and Ready in 2+ Years stages, and the development actions needed for each; a set of ground rules for respectful and unbiased discussion; and a post-workshop action plan template with owners and 90-day milestones. The guide should be usable by an HR facilitator with no external support.","tags":["succession-planning","talent","leadership"],"author":"AINOW","created":"2024-02-15T10:45:00Z","featured":false},

    {"id":"hr-11","title":"Internship Program Design Blueprint","prompt":"You are an early-career talent lead at a 600-person technology company. Design a 12-week summer internship program for 20 software engineering interns. The blueprint should cover: a week-by-week curriculum balancing real project work, structured learning sessions, and networking events; an onboarding checklist for the intern's first two days; a manager guide for setting intern projects with appropriate scope and mentorship cadence; a midpoint review process with a written feedback form; a final presentation format with an audience of senior engineers and product managers; a conversion offer decision process with criteria and timeline; and a post-program survey to measure intern NPS and identify improvements. Include specific activities for each week during weeks 1, 2, and 12. Assume all interns are remote-eligible but the company has a New York office available.","tags":["talent-acquisition","early-careers","program-design"],"author":"AINOW","created":"2024-02-15T10:50:00Z","featured":false},

    {"id":"hr-12","title":"Hiring Manager Training Workshop","prompt":"You are an HR Business Partner building a hiring manager enablement program. Design a 3-hour hiring manager training workshop for 15 managers who are new to conducting structured interviews. The workshop agenda should include: a 20-minute session on why unstructured interviews have low predictive validity, with data; a 40-minute interactive session on writing and delivering behavioral questions using the STAR framework; a 30-minute module on cognitive biases in hiring (halo effect, affinity bias, recency bias) with practical mitigation techniques; a 45-minute practice session where managers conduct mock interviews with a peer and receive structured feedback; a 20-minute session on legally compliant vs prohibited interview questions with 10 real examples of each; and a 25-minute debrief and Q&A. Include all facilitator notes, slide talking points, and the mock interview scenario to use in the practice session.","tags":["hiring","training","talent-acquisition"],"author":"AINOW","created":"2024-02-15T10:55:00Z","featured":false},

    {"id":"hr-13","title":"Annual Performance Review Framework","prompt":"You are the Head of People at a 250-person technology services company. Design a complete annual performance review framework to replace a legacy 'manager rates employee 1–5' system that has become a source of manager frustration and employee disengagement. The new framework should include: a philosophy statement explaining what the review is for and what it is not for; a self-assessment template (8–10 questions) that surfaces accomplishments, growth areas, and career aspirations without creating unnecessary anxiety; a manager assessment guide with rating dimensions, behavioral anchors, and calibration instructions; a peer feedback process (who selects peers, how many, what questions, how results are used); a calibration session guide for managers to align ratings across teams; a compensation linkage policy explaining how ratings translate to merit increases and bonuses; and a communication template for managers to deliver review outcomes in a 1:1 conversation. The framework should be implementable by a 3-person HR team.","tags":["performance-management","reviews","hr-ops"],"author":"AINOW","created":"2024-02-15T11:00:00Z","featured":true},

    {"id":"hr-14","title":"Underperformance Conversation Script","prompt":"You are a seasoned HR Business Partner coaching a first-time manager named Jordan. Jordan manages a team of 6 software engineers. One engineer, Alex, has been delivering work that consistently requires significant rework, has missed two sprint commitments in the past month, and has been withdrawn in team meetings. Jordan has not yet addressed this directly with Alex. Write a detailed script for the first performance conversation Jordan should have with Alex. The script should: open with genuine curiosity rather than accusation; present specific observable behaviours, not personality judgments; ask open questions to understand root causes (personal circumstances, unclear expectations, skill gap, or disengagement); move to collaborative problem-solving; end with a clear, documented agreement on next steps with a follow-up date. Include stage directions noting Jordan's body language and tone at each step. Also include a 'what not to say' sidebar with 5 phrases Jordan must avoid and why.","tags":["performance-management","coaching","employee-relations"],"author":"AINOW","created":"2024-02-15T11:05:00Z","featured":false},

    {"id":"hr-15","title":"OKR Alignment Facilitation for HR Teams","prompt":"You are an organizational effectiveness consultant. Facilitate the process of building quarterly OKRs for a 12-person HR department at a scaling technology company (currently 400 employees, targeting 650 by year-end). Lead the team through: a 30-minute context-setting exercise linking HR OKRs to the company's three strategic priorities (revenue growth, product-market expansion, and operational efficiency); a process for identifying the HR department's 3 most impactful Objectives for the quarter; for each Objective, a method for generating 3–4 Key Results that are measurable, time-bound, and ambitious but achievable; a scoring rubric for Key Results to distinguish output metrics from outcome metrics; a biweekly OKR review cadence and format; and a template for the HR leader's OKR report to the CEO. Include examples of strong vs weak OKRs in the HR context with a short explanation of why each is strong or weak.","tags":["performance-management","strategy","hr-ops"],"author":"AINOW","created":"2024-02-15T11:10:00Z","featured":false},

    {"id":"hr-16","title":"360-Degree Feedback Survey Design","prompt":"You are an organizational psychologist. Design a 360-degree feedback survey for mid-level managers (managing teams of 5–15 people) at a 300-person professional services firm. The survey should: include separate question sets for direct reports, peers, and the manager's own manager, each tailored to the relationship; cover the competencies of strategic thinking, execution and accountability, people development, communication clarity, and handling conflict; use a 5-point behaviorally anchored rating scale (not generic Likert) with specific behavioral anchors at 1, 3, and 5 for each competency; include 3 open-text questions per rater group designed to surface specific examples; include instructions for the HR team on minimum rater thresholds before showing results; and a report template showing how to present results to the manager in a constructive development conversation. Provide the full survey text for all three rater versions.","tags":["performance-management","feedback","learning-development"],"author":"AINOW","created":"2024-02-15T11:15:00Z","featured":false},

    {"id":"hr-17","title":"High-Performer Retention Conversation Guide","prompt":"You are a senior HRBP. Write a complete guide for managers on how to conduct a proactive retention conversation with a high-performing employee who has been with the company for 3 years, is consistently rated 'Exceeds Expectations', and has recently been approached by recruiters (the manager learned this through a trusted mutual colleague, not surveillance). The guide should include: when and how to initiate the conversation without making the employee feel monitored; 8 open-ended questions that reveal what the employee values most, where they feel underserved, and what their 3-year career aspiration looks like; how to respond if the employee admits they are exploring other options, without making promises the company cannot keep; how to create a personalized stay plan based on what you learn; a follow-up cadence; and a one-page 'things that drive high performers away' reference card for managers to review before the meeting.","tags":["retention","performance-management","management"],"author":"AINOW","created":"2024-02-15T11:20:00Z","featured":false},

    {"id":"hr-18","title":"Manager Effectiveness Survey","prompt":"You are an HR Analytics lead. Design a quarterly Manager Effectiveness Survey to be administered to individual contributors across a 450-person technology company. The survey should: be completable in under 7 minutes; measure 6 dimensions of manager effectiveness: clarity of expectations, quality of feedback, psychological safety, recognition, career development support, and workload management; use a 5-point agreement scale with specific behaviorally worded statements (not vague questions); include 2 open-text questions; explain in the survey introduction how results are used and that responses are anonymous (with a minimum team size of 5 to protect anonymity); include the scoring methodology for computing a Manager Effectiveness Score; and specify thresholds that trigger an HR Business Partner review conversation with the manager. Provide the full survey text and the analysis and reporting framework.","tags":["performance-management","hr-analytics","management"],"author":"AINOW","created":"2024-02-15T11:25:00Z","featured":false},

    {"id":"hr-19","title":"Calibration Session Facilitation Script","prompt":"You are an HR Director facilitating a performance calibration session. Write a complete facilitation script for a 2-hour calibration session for 8 engineering managers who have completed their team's annual performance ratings. The session must: open with ground rules and the purpose of calibration (consistency and fairness, not changing every rating); include a 20-minute warm-up exercise to surface each manager's implicit rating standards; walk through a structured process for reviewing outlier ratings (highest and lowest) and flagging potential bias patterns (e.g. leniency, recency, or in-group bias); include a protocol for resolving disagreement between managers; cover the distribution expectation (not a forced curve, but an expectation that rating distributions reflect genuine performance variance); and close with a manager commitment to delivering feedback to their teams within 5 business days. Include facilitator notes on common derailment patterns and how to handle them.","tags":["performance-management","calibration","management"],"author":"AINOW","created":"2024-02-15T11:30:00Z","featured":false},

    {"id":"hr-20","title":"Performance Documentation Best Practices","prompt":"You are an employment law-aware HR Business Partner. Write a practical guide for managers on how to document employee performance issues in a way that is factually accurate, legally defensible, and useful as a coaching tool — not just a paper trail for termination. The guide should cover: the difference between documenting observations vs interpretations (with 10 before/after examples); how to record performance conversations in writing, including the date, what was said, and what was agreed; the correct way to document a verbal warning, a written warning, and a final warning; how to store records securely and who should have access; how long to retain performance records; how to document performance improvements and positive contributions alongside problems (to avoid one-sided files); and common documentation mistakes that create legal risk, with examples of legally problematic language and corrected alternatives. This guide should be readable by a manager with no HR background.","tags":["performance-management","legal","hr-ops"],"author":"AINOW","created":"2024-02-15T11:35:00Z","featured":false},

    {"id":"hr-21","title":"Promotion Criteria and Process Design","prompt":"You are a People Operations lead. Design a transparent, consistent promotion process for individual contributor to manager transitions at a 350-person software company where promotions have historically been informal and manager-dependent. The process should include: a written set of promotion criteria for the IC-to-manager track covering competency expectations, performance history requirements, and readiness indicators; a nomination process with a standardized promotion packet template (self-assessment, manager recommendation, peer input, evidence of impact); a calibration committee composition and meeting cadence; a decision timeline that gives managers and employees predictability; a notification and communication plan for both approved and declined candidates; a development feedback template for declined candidates that gives them a concrete path forward; and an equity audit checkpoint ensuring that promotion rates are reviewed by gender, ethnicity, and tenure annually. Include the full promotion packet template.","tags":["performance-management","career-development","dei"],"author":"AINOW","created":"2024-02-15T11:40:00Z","featured":false},

    {"id":"hr-22","title":"Involuntary Termination Script and Checklist","prompt":"You are a senior HR Business Partner. Write a complete guide for conducting an involuntary termination meeting for a salaried employee whose employment is ending due to sustained underperformance following a completed PIP. The guide should include: a pre-meeting checklist covering IT access revocation timing, severance paperwork preparation, witness protocol, and room booking; a word-for-word opening script that is clear, direct, and compassionate (under 90 seconds, no ambiguity about whether the person still has a job); a script for the employee asking to be given another chance, and how to respond firmly but humanely; how to present the severance package and separation agreement; information about COBRA, final paycheck, and reference policy; a checklist of items to collect (laptop, badge, keys); a post-meeting HR debrief template; and a communication template for announcing the departure to the team without disclosing the reason. Include a section on what not to say and why.","tags":["employee-relations","termination","legal"],"author":"AINOW","created":"2024-02-15T11:45:00Z","featured":true},

    {"id":"hr-23","title":"L&D Strategy for a Scaling Startup","prompt":"You are the Head of Learning & Development joining a 180-person startup that has no formal L&D infrastructure. The company is growing 80% year-over-year and managers are struggling to lead effectively. Write a 12-month L&D strategy for your first year. The strategy should include: a learning needs assessment process (what data you will collect and how) to be completed in your first 60 days; a prioritized list of the top 5 learning initiatives with business case rationale for each; a manager development program design covering the topics new managers most urgently need (feedback, delegation, difficult conversations, hiring, and performance management); a decision framework for build vs buy vs curate learning content; a measurement framework linking L&D investment to business outcomes (not just completion rates); a budget proposal for a $180,000 annual L&D budget with line-item allocation; and a stakeholder communication plan for getting CEO and CFO buy-in. Be concrete and avoid generic L&D consulting language.","tags":["learning-development","strategy","hr-ops"],"author":"AINOW","created":"2024-02-15T11:50:00Z","featured":true},

    {"id":"hr-24","title":"New Manager Onboarding Program","prompt":"You are an L&D specialist. Design a 90-day onboarding program for first-time managers (recently promoted from individual contributor) at a 400-person technology company. The program should be structured around three phases: Foundation (days 1–30) covering the company's management philosophy, their new responsibilities, and tools like 1:1s and feedback frameworks; Application (days 31–60) where they apply concepts to real situations with coaching support; and Consolidation (days 61–90) including peer learning circles and a capstone reflection. For each phase, specify: the learning objectives; specific workshops or self-paced modules with content descriptions; touchpoints with HR and a senior manager mentor; a practical assignment; and a checkpoint assessment. The program should require approximately 4 hours per week of structured time. Include the full first-week schedule and a new manager onboarding checklist.","tags":["learning-development","management","onboarding"],"author":"AINOW","created":"2024-02-15T11:55:00Z","featured":false},

    {"id":"hr-25","title":"Leadership Development Program Design","prompt":"You are an organizational development consultant. Design a 6-month leadership development program for 20 high-potential senior managers at a global financial services firm being prepared for VP-level roles within 18 months. The program design should include: a cohort selection criteria and nomination process; a learning curriculum covering strategic thinking, executive presence, enterprise thinking, organizational influence, and leading through change; a mix of modalities including workshops, executive coaching (individual and group), peer action learning sets, a business challenge project, and exposure to the C-suite; a pre-program 360 assessment and post-program reassessment to measure leadership growth; a sponsorship model pairing each participant with an executive sponsor; a schedule showing the monthly cadence across 6 months; a program ROI measurement framework; and a graduation event design. Budget assumption is $15,000 per participant. Include a sample agenda for the first program workshop.","tags":["learning-development","leadership","talent"],"author":"AINOW","created":"2024-02-15T12:00:00Z","featured":false},

    {"id":"hr-26","title":"Onboarding Experience Design","prompt":"You are a People Experience designer. Redesign the onboarding experience for new hires joining a 500-person e-commerce company in individual contributor roles. The current onboarding is a 2-day death-by-PowerPoint session that new hires consistently rate 4.2/10. The new experience should cover the first 90 days. Design the experience including: a pre-boarding engagement sequence starting from offer acceptance to Day 1 (what the company sends, what it asks, what access it provides); a Day 1 agenda that balances human connection, practical setup, and context-setting without overwhelming; a 30-60-90 day learning milestone structure; an onboarding buddy program with a selection guide and weekly conversation prompts; a manager's onboarding guide specifying their role week by week; a role-specific learning path template; and a 30-day and 90-day new hire check-in survey. Explain the reasoning behind each design decision. The redesign should require no additional headcount to run.","tags":["onboarding","learning-development","employee-experience"],"author":"AINOW","created":"2024-02-15T12:05:00Z","featured":false},

    {"id":"hr-27","title":"Skills Gap Analysis Framework","prompt":"You are a workforce planning specialist. Build a skills gap analysis framework for a 300-person insurance company undergoing digital transformation. The company needs to identify which roles are at risk of automation, which employees have transferable skills for new digital roles, and what learning investments are needed over the next 3 years. The framework should include: a methodology for mapping current role skills to a skills taxonomy; a process for assessing individual skill levels through manager input, self-assessment, and skills testing; a scoring model to identify critical skill gaps at the role and individual level; a prioritization matrix that distinguishes gaps that represent business risk from gaps that represent growth opportunities; a reporting format for presenting findings to the executive team; a template for individual skill development plans; and a set of data sources and tools for maintaining skills data over time. Include a worked example using the role of 'Insurance Underwriter' transitioning toward a data-augmented underwriting model.","tags":["learning-development","workforce-planning","hr-analytics"],"author":"AINOW","created":"2024-02-15T12:10:00Z","featured":false},

    {"id":"hr-28","title":"Coaching Culture Implementation Plan","prompt":"You are an organizational development lead. Create a 12-month implementation plan for building a coaching culture across a 600-person retail organization where most managers currently manage through directive instruction rather than developmental questioning. The plan should include: a definition of coaching culture and how it manifests in day-to-day management behaviour; a change readiness assessment process; a phased rollout starting with a pilot group of 20 managers; a core coaching skills training program (3-day curriculum outline with session topics, practice activities, and key models such as GROW); a peer coaching pairs program with a matching process and conversation structure; a measurement approach including a baseline and 6-month re-measurement of team psychological safety scores; a senior leader role-modelling campaign; and a sustainability plan for year 2 and beyond. Include the GROW coaching framework as a one-page reference card for managers.","tags":["learning-development","coaching","culture"],"author":"AINOW","created":"2024-02-15T12:15:00Z","featured":false},

    {"id":"hr-29","title":"Learning Measurement Framework","prompt":"You are an L&D analytics specialist. Build a learning measurement framework for a 400-person professional services firm that currently measures only training completion rates and satisfaction scores. The framework should enable the L&D team to demonstrate business impact and justify a $500,000 annual training budget. Apply Kirkpatrick's four levels and Phillips's ROI methodology to design: Level 1 (Reaction) — a redesigned post-training survey that captures more useful signal than a happiness score; Level 2 (Learning) — a framework for selecting the right knowledge assessment method for different learning types; Level 3 (Behavior) — a 60-day post-training manager observation and self-report protocol; Level 4 (Results) — a process for identifying and isolating the business metrics linked to each learning program; Level 5 (ROI) — a calculation methodology for three programs: a sales negotiation skills program, a new manager essentials program, and a compliance training program. Include a reporting template for the L&D quarterly business review.","tags":["learning-development","hr-analytics","strategy"],"author":"AINOW","created":"2024-02-15T12:20:00Z","featured":false},

    {"id":"hr-30","title":"Mentoring Program Design","prompt":"You are an L&D Manager. Design a 6-month formal mentoring program for 30 mentee-mentor pairs at a 700-person healthcare technology company, focused on accelerating the development of high-potential women and underrepresented minorities into senior roles. The program design should include: mentee eligibility criteria and application process; mentor selection criteria and how to recruit senior leaders as mentors; a matching algorithm or process that considers role goals, functional diversity, and chemistry; a pre-program briefing for both mentors and mentees with expectation-setting; a session guide for the first meeting (agenda, conversation starters, goal-setting template); a monthly structured topic guide for months 1–6; a mid-program check-in survey for both parties; guidelines for what constitutes appropriate vs inappropriate mentoring relationships; a program close-out including final reflection and next steps; and outcome metrics. Include the first-meeting conversation guide in full.","tags":["learning-development","dei","talent"],"author":"AINOW","created":"2024-02-15T12:25:00Z","featured":false},

    {"id":"hr-31","title":"AI Literacy Training for Non-Technical Employees","prompt":"You are an L&D specialist designing a training program for the wave of AI tool adoption across a 500-person media company. Most employees are non-technical and range from skeptical to enthusiastic about AI. Design a half-day AI Literacy Workshop for individual contributors in marketing, finance, and HR. The workshop should cover: what generative AI actually is and how it works, in plain language with no jargon; a live demonstration of 3 practical use cases relevant to each audience's work (creating first drafts, summarizing documents, structuring analysis); hands-on practice with a company-approved AI tool; a critical thinking module on AI limitations: hallucination, bias, and over-reliance; the company's AI usage policy including what data must never be pasted into external AI tools; prompt writing basics with before/after examples; and a 'how to spot AI-generated content' segment. Include the full facilitator agenda with timings, all exercise instructions, and the take-home reference card.","tags":["learning-development","ai","hr-technology"],"author":"AINOW","created":"2024-02-15T12:30:00Z","featured":true},

    {"id":"hr-32","title":"Career Pathing Framework","prompt":"You are a talent management specialist. Build a career pathing framework for individual contributors in the Sales function at a 400-person SaaS company. Currently, the only visible path is Account Executive to Senior AE to Manager, which is causing high turnover among top performers who do not want to manage people. The framework should include: an IC (individual contributor) track that runs parallel to the management track, with equivalent level names, responsibilities, and compensation bands at each level; a description of the skills, impact, and scope expected at each level on both tracks; a transparent process for moving between levels including how decisions are made, who is involved, and timelines; lateral move options into adjacent functions (Sales Engineering, Customer Success, Revenue Operations) with a skills bridge guide; a career conversation guide for managers including questions to use in quarterly career 1:1s; and a self-assessment tool for AEs to evaluate where they are and where they want to go. Include the full level matrix for the IC sales track from AE through Principal AE.","tags":["career-development","learning-development","retention"],"author":"AINOW","created":"2024-02-15T12:35:00Z","featured":false},

    {"id":"hr-33","title":"Workplace Investigation Protocol","prompt":"You are an HR Director at a 500-person company. A formal complaint has been filed by a marketing coordinator alleging that their direct manager repeatedly belittled them in front of the team, assigned them work outside their job description without explanation, and excluded them from key meetings after they raised a concern in a 1:1. Write a complete workplace investigation protocol for handling this complaint. Include: a decision tree for whether to investigate internally or retain an external investigator; a first-response checklist covering intake documentation, interim protective measures, and confidentiality obligations; a witness interview plan (who to interview, in what order, and why); a standardized investigative interview guide with opening, substantive, and closing phases; how to assess credibility and weigh conflicting accounts; a findings documentation template; a decision framework for remediation options; a communication plan for the complainant, the respondent, and the broader team; and an anti-retaliation monitoring plan. The protocol should be legally defensible and trauma-informed.","tags":["employee-relations","legal","investigation"],"author":"AINOW","created":"2024-02-15T12:40:00Z","featured":true},

    {"id":"hr-34","title":"Conflict Mediation Facilitation Guide","prompt":"You are a trained mediator and HR Business Partner. Two senior engineers on the same product team — one a 6-year company veteran and one hired 8 months ago from a competitor — are in open conflict. The conflict centres on architectural decision-making authority, code review tone, and a specific incident three weeks ago where one engineer publicly contradicted the other in a design review in front of 12 colleagues. Their manager has tried to address it informally and failed. Write a complete mediation facilitation guide for HR to run a structured mediation session. Include: a pre-mediation individual meeting guide for each participant (separate meetings, 45 minutes each); ground rules for the joint session; a structured opening statement; a facilitated exchange process using interests-based (not positions-based) dialogue; a joint problem-solving phase; a written agreement template; and a follow-up plan at 2 weeks and 6 weeks. Include scripts for common derailment moments such as one party blaming the other or shutting down.","tags":["employee-relations","conflict","mediation"],"author":"AINOW","created":"2024-02-15T12:45:00Z","featured":false},

    {"id":"hr-35","title":"Psychological Safety Assessment and Action Plan","prompt":"You are an organizational psychologist. A 45-person product engineering team at a 600-person technology company has consistently scored in the bottom quartile on psychological safety in the annual engagement survey for two consecutive years. The team's manager has been in role for 14 months and is technically strong but received feedback about being dismissive of ideas in team meetings. Design a comprehensive psychological safety assessment and intervention for this team. Include: a diagnostic approach combining survey data re-analysis, focus groups, and 1:1 interviews to identify the specific safety-undermining behaviours; a structured feedback conversation framework for the HR Business Partner to use with the manager; a team-level intervention sequence over 90 days including a team workshop, a new team agreements process, and new meeting norms; manager coaching objectives and session themes; a 90-day re-measurement plan; and a risk escalation trigger (at what point does this become a performance or conduct issue for the manager). Include the psychological safety diagnostic survey (Amy Edmondson's adapted framework).","tags":["employee-relations","culture","management"],"author":"AINOW","created":"2024-02-15T12:50:00Z","featured":false},

    {"id":"hr-36","title":"Layoff Communication Playbook","prompt":"You are a Chief People Officer advising a 400-person SaaS company that needs to reduce its workforce by 18% (approximately 72 roles) due to a revenue shortfall and shift in product strategy. Write a complete layoff communication playbook. Include: a pre-announcement preparation checklist (legal review, severance calculation, IT access, manager briefing); a board and executive communication sequence; a manager briefing guide (what to say, what not to say, and how to answer 'why is this person being let go and not someone else'); the actual notification meeting script (15 minutes, clear and compassionate, delivered in person or video where possible); a same-day all-company communication from the CEO that is honest about what happened and does not feel scripted; a communication for the employees who remain, addressing survivor guilt and uncertainty; an FAQ document for managers; a press response holding statement; and a 30-day culture stabilisation plan. Include specific language to use and avoid at each stage.","tags":["employee-relations","crisis","communications"],"author":"AINOW","created":"2024-02-15T12:55:00Z","featured":true},

    {"id":"hr-37","title":"Exit Interview Program Redesign","prompt":"You are a People Analytics lead. The company's current exit interview is a 5-question form emailed to departing employees that has a 23% completion rate and yields data too vague to act on. Redesign the exit interview program for a 450-person technology company targeting 70%+ completion and actionable insights. The redesign should include: a decision on format (live conversation vs survey vs both) with rationale; a timing strategy for when in the offboarding process to conduct the interview; the full question set (10–12 questions) covering departure drivers, manager relationship, culture experience, and what would have caused the employee to stay; a response handling protocol distinguishing feedback that should be escalated from feedback that goes into trend analysis only; a data analysis process including how to categorize and quantify responses; a quarterly reporting template that connects exit data to engagement survey themes and turnover KPIs; and a closed-loop process where findings are shared with leadership and tracked for action. Include the redesigned interview question set in full.","tags":["employee-relations","hr-analytics","retention"],"author":"AINOW","created":"2024-02-15T13:00:00Z","featured":false},

    {"id":"hr-38","title":"Remote Work Policy","prompt":"You are an HR Director at a 350-person technology company transitioning to a permanent hybrid model after two years of fully remote work. Write a comprehensive remote and hybrid work policy. The policy should cover: eligibility criteria (which roles are eligible for remote-only, hybrid, or must be fully on-site, with a rationale for each category); the process for requesting and approving a remote or hybrid arrangement; manager responsibilities for ensuring remote employees have equitable access to information, visibility, and development opportunities; core collaboration hours (the hours during which all employees must be available regardless of location, and the rationale for the specific hours chosen); home office equipment and stipend policy ($1,500 setup allowance, $75/month internet and phone stipend); data security requirements for remote workers; international remote work restrictions with the reason; performance management for remote employees; and policy review cadence. Write in plain English with numbered sections and a brief summary for new employees.","tags":["employee-relations","remote-work","policy"],"author":"AINOW","created":"2024-02-15T13:05:00Z","featured":false},

    {"id":"hr-39","title":"Employee Wellbeing Program Strategy","prompt":"You are the Head of Total Rewards and Wellbeing. Design a holistic employee wellbeing strategy for a 500-person financial services company where the most recent engagement survey showed that 61% of employees report high or very high levels of work-related stress, 38% say they frequently work more than 50 hours per week, and mental health was the number-one benefit request in the benefits feedback survey. The strategy should cover four wellbeing dimensions: physical, mental, financial, and social. For each dimension include: a diagnosis of the current state; 3 concrete initiatives with implementation details, cost estimate, and expected impact; quick wins implementable in the first 30 days; and metrics to track improvement. Also include: a senior leader role-modelling campaign; a manager toolkit for recognising and responding to signs of employee burnout; a policy change recommendation (e.g. meeting-free afternoons, email after-hours norms); and an annual calendar of wellbeing touchpoints. Total program budget is $400,000 per year for 500 employees.","tags":["wellbeing","culture","total-rewards"],"author":"AINOW","created":"2024-02-15T13:10:00Z","featured":false},

    {"id":"hr-40","title":"Grievance Procedure Policy","prompt":"You are an employment law-informed HR professional. Draft a formal employee grievance procedure for a 600-person UK-based manufacturing company, compliant with the ACAS Code of Practice on Disciplinary and Grievance Procedures. The policy should include: a statement of purpose and scope; definitions distinguishing a grievance from a complaint and from a disciplinary matter; an informal resolution step with a 5-day response target; a formal grievance submission process with a written form template; Stage 1 (line manager investigation) with a 10-working-day investigation and response timeline; Stage 2 (senior manager appeal) with a 15-working-day timeline; Stage 3 (independent panel appeal) as a final internal step; a written record-keeping requirement; the employee's right to be accompanied at each formal stage; an anti-retaliation commitment; confidentiality obligations for all parties; and the relationship between the grievance procedure and the disciplinary procedure when issues are concurrent. The policy should be written at a reading level appropriate for shop-floor employees.","tags":["employee-relations","policy","legal"],"author":"AINOW","created":"2024-02-15T13:15:00Z","featured":false},

    {"id":"hr-41","title":"Employee Handbook: Core Policies Section","prompt":"You are an HR writer. Draft the Core Policies section of an employee handbook for a 200-person US-based technology startup operating in California, New York, and Texas. The section should cover the following policies, each written clearly and concisely (not in legal jargon): Equal Employment Opportunity and Anti-Discrimination (covering all legally protected characteristics); Anti-Harassment and Anti-Bullying (including a clear reporting process and a statement on retaliation); At-Will Employment (and what that means in plain English); Confidentiality and Intellectual Property Assignment (what the company owns and why); Acceptable Use of Company Technology (what is permitted and what is not); Code of Conduct (5 core behavioural expectations); and Conflicts of Interest (disclosure obligation and examples). Each section should be 150–250 words, begin with a plain-language purpose statement, and end with a 'what to do if' action prompt. Include a handbook acknowledgment signature page.","tags":["policy","employee-relations","legal"],"author":"AINOW","created":"2024-02-15T13:20:00Z","featured":false},

    {"id":"hr-42","title":"Bereavement and Compassionate Leave Policy","prompt":"You are a People Operations Manager who believes how a company treats employees at their worst moments defines its culture more than its perks. Draft a bereavement and compassionate leave policy for a 300-person company that is genuinely generous and human, not a minimum-compliance document. The policy should cover: paid bereavement leave for immediate family (spouse/partner, child, parent, sibling) — recommend the number of days and justify the recommendation; paid leave for extended family (grandparent, in-law, close friend); pregnancy loss and infant loss, including miscarriage at any stage; leave to support a seriously ill family member (not bereavement but caregiving leave); a flexible return-to-work arrangement for employees following bereavement; manager guidance on how to respond when an employee experiences a loss, including language to use and avoid; an employee assistance programme signposting; and a statement on the company's values that contextualises the policy. Write the policy in warm, direct language — not legalese.","tags":["employee-relations","policy","wellbeing"],"author":"AINOW","created":"2024-02-15T13:25:00Z","featured":false},

    {"id":"hr-43","title":"Whistleblower Policy and Reporting System","prompt":"You are a compliance-aware HR Director. Draft a comprehensive whistleblower protection policy for a 700-person publicly listed company. The policy must cover: scope — what types of wrongdoing employees can report (financial fraud, safety violations, discrimination, bribery, data breaches, and regulatory violations); reporting channels — an internal ethics hotline, a direct email to the General Counsel, and an external independent reporting service with the contact details of the service; protections — specific legal protections in the US (Dodd-Frank, SOX, and state whistleblower laws) and a plain-English explanation of what retaliation means and that it is strictly prohibited; the investigation process — who receives reports, the independence requirements for investigators, the timeline (initial acknowledgment within 2 business days, investigation closed within 45 days), and how findings are communicated back to the reporter; anonymity — what is protected and the limits of anonymity; and a commitment to no tolerance for retaliation with examples of retaliation. Include a one-page employee summary card.","tags":["compliance","legal","employee-relations"],"author":"AINOW","created":"2024-02-15T13:30:00Z","featured":false},

    {"id":"hr-44","title":"Culture Diagnostic and Action Planning Process","prompt":"You are an organizational consultant. A 450-person healthcare company is experiencing declining engagement scores (from 74% favourable to 61% favourable over two years), increasing voluntary turnover (from 11% to 19%), and a pattern of exit interview feedback citing 'lack of direction', 'my manager doesn't care about my development', and 'too much politics'. Design a culture diagnostic and 12-month action planning process. The diagnostic phase (months 1–2) should include: engagement data re-analysis methodology; a focus group design (who to include, facilitator guide, topic areas); a culture observation protocol for HR to use during site and team visits; a leadership interview guide; and a synthesis process for identifying the top 3 root cause themes. The action planning phase (months 3–12) should include: a co-design process with employees for culture actions; a communication plan; a prioritisation framework; a manager accountability mechanism; and a monthly measurement dashboard. Include the focus group facilitator guide in full.","tags":["culture","employee-relations","strategy"],"author":"AINOW","created":"2024-02-15T13:35:00Z","featured":false},

    {"id":"hr-45","title":"Compensation Philosophy and Band Design","prompt":"You are a Total Rewards Director at a 400-person Series D technology company. Write a complete compensation philosophy document and salary band design methodology. The philosophy section should cover: the company's market positioning target (e.g. 65th percentile of market) and the rationale for that specific target; the definition of the company's talent market (which companies it is competing with for talent, and why); the role of equity in total compensation; how compensation decisions are made and who has authority at each level; the company's approach to pay transparency (what is shared and with whom); and the annual review cycle. The band design methodology section should cover: which data sources to use (specify actual survey providers like Radford, Levels.fyi, Pave, or Mercer and what each is best for); how to construct a salary range with a midpoint, range minimum, and range maximum; how compa-ratio is calculated and used; how to handle employees who fall outside their band; and how to adjust bands annually. Include a worked example building a band for a Staff Software Engineer.","tags":["compensation","total-rewards","strategy"],"author":"AINOW","created":"2024-02-15T13:40:00Z","featured":true},

    {"id":"hr-46","title":"Pay Equity Audit Methodology","prompt":"You are a compensation analytics specialist. Design a rigorous pay equity audit methodology for a 600-person company that wants to identify and remediate unexplained pay gaps before they are externally reported or result in legal claims. The methodology should include: scope definition (which employee populations to include, which compensation elements to analyse); data preparation steps including job levelling validation and role family grouping; a statistical regression model specification identifying the legitimate pay factors (job level, function, performance rating, tenure, and geography) to use as control variables; a threshold for flagging unexplained gaps as material (specify the percentage and statistical significance level and explain why); a process for reviewing flagged cases through a joint HR-Finance committee; a remediation budgeting approach that prioritises the most material gaps; a communication plan for employees who receive remediation adjustments; and an annual re-audit cadence. Include the regression model variables table and a sample output showing how to interpret results. Be specific about the statistical method used.","tags":["compensation","dei","hr-analytics"],"author":"AINOW","created":"2024-02-15T13:45:00Z","featured":false},

    {"id":"hr-47","title":"Total Rewards Statement Design","prompt":"You are a Total Rewards communications specialist. Design a comprehensive annual Total Rewards Statement for employees at a 500-person company, intended to increase employees' perceived value of their total compensation package (surveys show that 68% of employees underestimate the value of their benefits by more than 20%). The statement should include: base salary (annualised); actual bonus paid in the last 12 months; equity value (current estimated value of unvested equity, with an explanatory note); employer pension/401k contribution; medical, dental, and vision premiums paid by the employer; life insurance and disability insurance value; paid time off monetary value (days x daily rate); parental leave policy value; L&D spend; wellbeing benefits; and any other perks with estimated value. Include a design brief specifying the layout, data visualisation approach (suggest a total compensation breakdown chart), copy tone, and a plain-English 'what this means for you' narrative. Also include a FAQ section addressing the top 5 questions employees ask when they see their statement.","tags":["compensation","total-rewards","communications"],"author":"AINOW","created":"2024-02-15T13:50:00Z","featured":false},

    {"id":"hr-48","title":"Variable Pay Plan Design","prompt":"You are a compensation consultant. Design a variable pay plan for a 60-person B2B SaaS sales team at a company with $40M ARR targeting $65M by year-end. The plan should cover: the overall pay mix philosophy (what percentage of on-target earnings (OTE) should be base vs variable, and why, for Account Executives, Senior AEs, and Sales Managers separately); the commission structure for new business (rate, accelerators above 100% of quota, and decelerators below 50% of quota); the commission structure for expansion and renewal revenue; clawback provisions if a customer churns within 90 days of close; a Sales Development Representative incentive plan (meeting-based vs pipeline-based and why); a Sales Manager plan that rewards team performance without creating a pure override; a SPIF (short-term performance incentive) policy for strategic deal types; quarterly vs monthly payout timing and rationale; and a plan documentation template to give to each rep at the start of each year. Include a worked example showing total earnings for an AE at 80%, 100%, and 130% of quota.","tags":["compensation","sales","total-rewards"],"author":"AINOW","created":"2024-02-15T13:55:00Z","featured":false},

    {"id":"hr-49","title":"Benefits Benchmarking and Redesign","prompt":"You are the Head of Benefits at a 400-person company preparing for an annual benefits renewal. Employee survey data shows that 44% of employees rate the current benefits package as 'average or below average' compared to market, and the top 3 requests are better mental health support, fertility benefits, and student loan repayment assistance. Your total benefits budget is $8,500 per employee per year. Write a benefits redesign proposal that includes: a benchmarking analysis framework (which data sources to use, which companies to benchmark against, and how to weigh cost vs perceived value); a recommendation for 3 new benefits to add with vendor options, cost estimates, and employee value narrative for each; a recommendation for 1–2 existing benefits to cut or reduce to fund the new additions; a benefits communication plan to ensure employees know and use what they have (most employees use less than 40% of available benefits); and a measurement framework including utilisation tracking and benefits satisfaction survey design. Include the cost-benefit analysis for the mental health benefit addition.","tags":["compensation","total-rewards","employee-experience"],"author":"AINOW","created":"2024-02-15T14:00:00Z","featured":false},

    {"id":"hr-50","title":"Equity Compensation Explainer for Employees","prompt":"You are an HR Business Partner helping employees understand their equity compensation. Write a comprehensive plain-English guide to equity compensation for employees at a Series C startup who have received stock option grants. The guide should cover: what stock options are and why the company uses them as part of compensation; the difference between ISOs (Incentive Stock Options) and NSOs (Non-Qualified Stock Options); what 'vesting' means, how a 4-year vest with a 1-year cliff works, and a worked numerical example; what the 'strike price' or 'exercise price' is and why it matters; the 409A valuation and why it exists; how to think about the current paper value of options vs the expected future value; the 90-day post-termination exercise window and why it is important to understand before leaving the company; the basic tax implications of exercising ISOs vs NSOs (note this is educational, not tax advice); what dilution is and how subsequent funding rounds affect ownership percentage; and a glossary of 15 key equity terms. Write as if explaining to a smart non-financial person. Include 3 worked numerical examples.","tags":["compensation","education","employee-experience"],"author":"AINOW","created":"2024-02-15T14:05:00Z","featured":false},

    {"id":"hr-51","title":"Executive Compensation Framework","prompt":"You are a compensation consultant advising the Compensation Committee of a 300-person private technology company. Design an executive compensation framework for a C-suite of 6 leaders (CEO, CFO, CTO, CPO, CMO, CRO). The framework should cover: the philosophy for how executive pay should be set (market data, peer group, and pay-for-performance linkage); the recommended pay mix (base, annual bonus, and long-term equity) at target and maximum for each role; a peer group selection methodology for benchmarking C-suite roles in the private market; the design of the Annual Incentive Plan (AIP) including performance metrics selection (recommend specific metrics for each role), weighting, and payout curve; the design of the Long-Term Incentive (LTI) equity program including instrument type (stock options vs RSUs), vesting schedule, and performance conditions if applicable; a total compensation comparison table showing target TTC vs 50th and 75th percentile of market; and a governance process for Compensation Committee approval. Include a worked example for the CRO role.","tags":["compensation","executive","strategy"],"author":"AINOW","created":"2024-02-15T14:10:00Z","featured":false},

    {"id":"hr-52","title":"Salary Transparency Communication Plan","prompt":"You are a Chief People Officer who has decided to move to full internal salary transparency — all employees will be able to see all salary bands and where they fall within their band. This is a significant culture change at a 350-person company where salary has historically been a closely guarded individual matter. Write a complete change management and communication plan for the transition. Include: a case for why transparency creates fairness (include the research evidence); the key anxieties employees and managers will have and how to address each one specifically; a pre-launch manager briefing (what managers need to know and be able to answer before the announcement goes out); the all-company announcement email from the CHRO — written in full, not as a template; a town hall Q&A script with 15 anticipated questions and model answers; a guide for employees on how to interpret their band position and compa-ratio; a process for employees who discover they are paid below the midpoint of their band to raise a concern; and a 30-day and 90-day sentiment check-in plan. The tone should be confident and values-driven, not defensive.","tags":["compensation","culture","communications"],"author":"AINOW","created":"2024-02-15T14:15:00Z","featured":false},

    {"id":"hr-53","title":"DEI Strategy and Roadmap","prompt":"You are the first Head of Diversity, Equity and Inclusion hired at a 500-person technology company. The company is 72% white, 76% male in engineering roles, has no formal DEI programs, and is under pressure from the board and employees to show meaningful progress. Write an 18-month DEI strategy and roadmap. The strategy should be grounded in evidence, not performative. Include: a diagnostic phase (months 1–3) covering the data analysis framework (representation data, pay equity, promotion parity, survey inclusion scores), a stakeholder listening tour design, and a current state summary format; a strategic framework covering 3 focus areas with specific, measurable goals; an action plan for each focus area with initiatives, owners, timelines, and success metrics; a business case section explaining the links between inclusion and business outcomes using research evidence; a budget proposal ($350,000 annual budget for 500 employees); a governance model including an executive DEI Council and employee resource group framework; and a communication strategy. Be specific — avoid generic 'celebrate diversity' language. Include the first 90-day action plan in detail.","tags":["dei","strategy","culture"],"author":"AINOW","created":"2024-02-15T14:20:00Z","featured":true},

    {"id":"hr-54","title":"Inclusive Hiring Process Audit","prompt":"You are a DEI consultant conducting a hiring process audit for a 400-person financial services company that has been struggling to increase representation of Black and Hispanic candidates at the mid-senior level despite running targeted recruitment campaigns. Write a complete inclusive hiring process audit. The audit should cover: a review methodology for assessing each stage of the hiring funnel for bias risk (sourcing channels, job description language, resume screening, interview process, offer stage); a data analysis framework to identify where in the funnel underrepresented candidates are disproportionately dropping out; specific bias mechanisms to look for at each stage with diagnostic questions; a structured interview adoption assessment with a recommendation on whether structured interviews alone are sufficient or whether additional interventions are needed; a diverse interview panel policy with a feasibility assessment; a blind resume screening pilot design; a sourcing channel diversification plan including HBCUs, professional associations, and community partnerships; and a set of 6-month and 12-month metrics. Include a funnel drop-off analysis template.","tags":["dei","hiring","hr-analytics"],"author":"AINOW","created":"2024-02-15T14:25:00Z","featured":false},

    {"id":"hr-55","title":"Employee Resource Group Framework","prompt":"You are an Inclusion Programs Manager. Design a comprehensive Employee Resource Group (ERG) framework for a 600-person company that currently has 3 informal affinity groups with no formal structure, no budget, and no leadership connection. The framework should cover: a formal ERG charter template specifying purpose, membership, leadership structure, and operating cadence; a governance model connecting ERGs to the DEI Council and HR; a budget allocation model (recommend an annual budget per ERG and how it scales with membership); an ERG leader selection and succession process; clarity on what ERGs are and are not responsible for (support vs accountability for DEI outcomes); an executive sponsor program with role expectations and a matching process; a cross-ERG collaboration mechanism; a reporting requirement (quarterly update format); a recognition and career development benefit for ERG leaders; and an annual ERG summit design. Include the full ERG charter template and the executive sponsor role description. Provide names for 5 ERGs typical for a tech company.","tags":["dei","culture","employee-relations"],"author":"AINOW","created":"2024-02-15T14:30:00Z","featured":false},

    {"id":"hr-56","title":"Unconscious Bias Training Redesign","prompt":"You are an L&D specialist with expertise in DEI. The company's current unconscious bias training is a 45-minute eLearning module that employees complete once during onboarding and never think about again. Research shows this format has minimal lasting impact on behaviour. Redesign the approach for a 550-person company. The new design should: explain why the single-session eLearning approach fails to change behaviour (cite the research); propose a multi-touchpoint approach integrated into existing manager workflows rather than a standalone training event; design a 3-hour manager workshop that goes beyond awareness to practice — include specific skill-building activities for the moments where bias most affects decisions (hiring, performance reviews, promotion decisions, and task allocation); design 4 quarterly 20-minute team huddle activities on specific bias topics; create a 'bias interrupter' card that managers can use before making people decisions; and propose a measurement approach that evaluates behaviour change not just awareness scores. Include the full manager workshop agenda and the bias interrupter card.","tags":["dei","learning-development","management"],"author":"AINOW","created":"2024-02-15T14:35:00Z","featured":false},

    {"id":"hr-57","title":"Inclusive Meeting Practices Guide","prompt":"You are an inclusion consultant. Write a practical Inclusive Meeting Practices guide for managers and employees at a 400-person global technology company with teams across 8 time zones and a mix of introverts and extroverts, native and non-native English speakers, and neurodiverse employees. The guide should cover: meeting design principles that ensure all voices have equitable opportunity to contribute; specific facilitation techniques for drawing out quieter participants without singling anyone out; how to run hybrid meetings (some in-room, some remote) equitably so remote participants are not second-class attendees; agenda design practices that allow preparation time for those who process ideas more slowly; how to make written English accessible to non-native speakers in meeting communications; an asynchronous meeting alternative for certain decision types; a guide to recognising and interrupting patterns of 'idea theft' (when a person's idea is repeated and credited to someone else); and a team meeting norms template that teams can customise. Include a one-page quick reference card for meeting facilitators.","tags":["dei","culture","management"],"author":"AINOW","created":"2024-02-15T14:40:00Z","featured":false},

    {"id":"hr-58","title":"Disability Inclusion Strategy","prompt":"You are a Disability Inclusion specialist. Design a disability inclusion strategy for a 700-person retail and e-commerce company where 4% of employees have disclosed a disability (well below the estimated 15–20% prevalence in the working population). The low disclosure rate suggests a culture where employees do not feel safe disclosing. The strategy should cover: a current state assessment framework (disclosure rate analysis, accommodations data, accessibility audit, and culture survey questions to add); a psychological safety for disclosure campaign including manager training on how to respond to disclosure and a communications campaign from senior leaders; the reasonable accommodations process redesign (from the current manager-handled informal process to a centrally managed, consistently applied process); accessibility improvements to the physical office environment and digital tools; a disability-confident recruiting initiative; a partnership with two disability employment organisations; and a 12-month measurement plan. Include the manager guide for responding to a disability disclosure conversation.","tags":["dei","disability","inclusion"],"author":"AINOW","created":"2024-02-15T14:45:00Z","featured":false},

    {"id":"hr-59","title":"Inclusion Index Survey Design","prompt":"You are a People Analytics specialist. Design an Inclusion Index for a 500-person company to be run as a standalone survey or as a module within the annual engagement survey. The index should measure inclusion as a lived experience, not just a feeling of general belonging. It should cover 5 dimensions: Fairness (do people believe decisions about them are made fairly?); Access (do people have equal access to information, networks, and opportunities?); Voice (do people feel their contributions are heard and credited?); Safety (do people feel safe to dissent, be different, and speak up?); and Belonging (do people feel they can bring a genuine version of themselves to work?). For each dimension: write 4 survey items using a 5-point frequency or agreement scale; provide a scoring methodology; identify the minimum score that represents a healthy baseline; and specify what actions a score below baseline should trigger. Include a demographic cut reporting framework, a note on intersectionality in reporting, and the minimum group size for reporting demographic breakdowns. Provide all 20 survey items in full.","tags":["dei","hr-analytics","culture"],"author":"AINOW","created":"2024-02-15T14:50:00Z","featured":false},

    {"id":"hr-60","title":"Global DEI Localisation Framework","prompt":"You are an International HR Director. A US-headquartered technology company with 800 employees across the US, UK, Germany, India, and Singapore is applying its US-designed DEI framework globally and encountering resistance. In Germany, works council representatives question the legal basis for collecting race and ethnicity data. In India, the approach is seen as culturally tone-deaf. In Singapore, caste has not been included as a diversity dimension. Design a Global DEI Localisation Framework that maintains global standards while respecting legal and cultural differences. The framework should cover: a global DEI foundation layer (non-negotiable principles that apply everywhere); a localisation methodology for adapting programs, data collection, and language for each region; specific guidance for each of the 5 geographies on legal constraints on data collection, locally relevant diversity dimensions, and culturally appropriate program design; a global DEI governance model that includes regional representation; and a translation and terminology guide. Include a one-page summary matrix comparing approaches across all 5 regions.","tags":["dei","global-hr","strategy"],"author":"AINOW","created":"2024-02-15T14:55:00Z","featured":false},

    {"id":"hr-61","title":"HR Tech Stack Evaluation Framework","prompt":"You are the Head of HR Technology at a 500-person company whose HR tech stack consists of a 7-year-old HRIS, a separate ATS that does not integrate with it, payroll processed in a third system, and L&D tracked in a spreadsheet. The CEO has approved a budget of $400,000 for year 1 of an HR tech transformation. Write a complete HR tech stack evaluation and selection framework. Include: a current state audit methodology (mapping all HR processes to current tools, identifying integration gaps and manual workarounds); a future state architecture design specifying the core systems needed and how they should integrate; a requirements-gathering process involving HR, Finance, IT, and employee representatives; an RFP template for an HRIS/HCM platform including functional requirements, integration requirements, security requirements, and vendor support requirements; a vendor scoring matrix with weighted criteria; a reference check guide for speaking to current customers of shortlisted vendors; an implementation risk assessment; and a total cost of ownership calculation framework. Include the RFP scoring matrix with suggested criteria and weights.","tags":["hr-technology","hr-ops","strategy"],"author":"AINOW","created":"2024-02-15T15:00:00Z","featured":true},

    {"id":"hr-62","title":"People Analytics Strategy","prompt":"You are a People Analytics lead building the function from scratch at a 600-person technology company. Currently HR makes most decisions based on intuition and limited data. The CHRO wants to build data-driven people decisions within 18 months. Write a People Analytics strategy for year 1. Include: a capability assessment framework for evaluating the current state of data, tools, skills, and stakeholder appetite; a use case prioritisation methodology to identify the 3 highest-value analytics projects to start with (from a list of options including attrition prediction, hiring funnel analysis, engagement driver analysis, pay equity, span of control optimisation, and manager effectiveness); a data infrastructure requirements list; a skills plan for the 2-person analytics team; an ethical use of people data framework covering consent, privacy, data minimisation, and algorithmic accountability; a stakeholder engagement plan for building analytical credibility with the business; and a 90-day quick win plan. Include a worked example of an attrition risk model specification: inputs, model type, outputs, and how managers should use it.","tags":["hr-analytics","strategy","hr-technology"],"author":"AINOW","created":"2024-02-15T15:05:00Z","featured":false},

    {"id":"hr-63","title":"Workforce Planning Model","prompt":"You are a strategic workforce planning specialist. Build a 3-year workforce planning model for a 400-person insurance company facing three simultaneous workforce pressures: 22% of the workforce is eligible to retire within 3 years, digital transformation is changing skill requirements in 40% of roles, and the company is planning to open two new regional offices. The model should include: a supply analysis framework (current headcount, attrition projection, internal promotion flow, retirement pipeline); a demand analysis framework (headcount needed by role family over 3 years based on business plan, skill mix changes driven by technology, and new office headcount); a gap analysis methodology (supply minus demand by role family and level); a scenario planning framework with 3 scenarios (base, optimistic growth, economic headwind); build vs buy vs borrow strategy recommendations for the top 5 identified gap areas; a talent pipeline investment plan; and a workforce planning dashboard specification. Include a worked example for the Underwriting function showing supply, demand, and gap analysis.","tags":["workforce-planning","hr-analytics","strategy"],"author":"AINOW","created":"2024-02-15T15:10:00Z","featured":false},

    {"id":"hr-64","title":"AI in HR Governance Framework","prompt":"You are the Chief People Officer of a 700-person company that is beginning to deploy AI tools across HR processes including resume screening, interview scheduling, engagement survey analysis, and attrition prediction. Write a comprehensive AI in HR Governance Framework. The framework should cover: a taxonomy of AI use cases in HR categorised by risk level (low, medium, high) with examples in each category; an AI procurement checklist for evaluating third-party HR AI vendors including questions on training data, bias testing, explainability, and audit rights; an employee disclosure standard — what employees should be told when AI is used in decisions about them; a human-in-the-loop requirement specifying which HR AI decisions must have a human review step and why; a bias monitoring protocol for deployed AI tools; a data privacy framework specifying what employee data can be used to train or run AI models; a process for employees to contest AI-influenced decisions; and a review cadence for the governance framework itself. Include the AI risk taxonomy table and the vendor assessment checklist.","tags":["hr-technology","ai","compliance"],"author":"AINOW","created":"2024-02-15T15:15:00Z","featured":true},

    {"id":"hr-65","title":"HRIS Implementation Project Plan","prompt":"You are an HR Technology Project Manager leading the implementation of a new HRIS (Workday) for a 550-person company. The implementation timeline is 9 months and the go-live date is fixed. Write a complete HRIS implementation project plan. Include: a phase breakdown (Discovery, Design, Build, Test, Train, Go-Live, Stabilisation) with milestone dates, key deliverables for each phase, and resource requirements; a data migration plan covering data quality assessment, data cleansing, mapping legacy fields to new system fields, and parallel-run testing; a configuration decision log template for tracking design decisions; a testing strategy covering unit testing, system integration testing, user acceptance testing (UAT), and parallel payroll run; a training plan for HR users, managers, and employees; a change management and communication plan for the workforce; a go-live readiness checklist; and a post-go-live hypercare support plan for the first 30 days. Also include a risk register with the top 8 implementation risks, their likelihood, impact, and mitigation actions.","tags":["hr-technology","hr-ops","project-management"],"author":"AINOW","created":"2024-02-15T15:20:00Z","featured":false},

    {"id":"hr-66","title":"HR Dashboard Design Specification","prompt":"You are a People Analytics lead designing the monthly HR dashboard for the CHRO and executive team of a 600-person company. Write a complete dashboard design specification. The dashboard should give the executive team a clear view of the health of the people function in under 10 minutes. Include: a dashboard philosophy (leading vs lagging indicators, and what questions the dashboard should answer); a set of 15–18 metrics across the categories of Workforce (headcount, open roles, time-to-fill, diversity representation), Retention (voluntary turnover rate, regrettable turnover rate, flight risk score), Performance (performance distribution, high-performer retention), Wellbeing and Engagement (eNPS, engagement score trend, absence rate), and Cost (cost per hire, training spend per employee, total HR cost as % of revenue); for each metric: a definition, data source, target or benchmark, and visualisation type; a traffic light (RAG) threshold system; a one-page summary format for the board; and a data freshness requirement. Include a mock wireframe description of the dashboard layout.","tags":["hr-analytics","hr-technology","strategy"],"author":"AINOW","created":"2024-02-15T15:25:00Z","featured":false},

    {"id":"hr-67","title":"Employee Self-Service Portal Content Strategy","prompt":"You are an HR Communications and Technology specialist. A 500-person company is launching an employee self-service (ESS) portal on their HRIS to reduce the volume of transactional HR queries (currently 180 per week to a 4-person HR team). Write a complete content strategy for the ESS portal. Include: a query log analysis methodology to identify the top 20 most common HR queries and their self-service resolution potential; a content architecture recommendation (how to organise the portal — by life event, by topic, or by audience); writing guidelines for HR self-service content (reading level, structure, length, tone); a content inventory for the top 10 content items needed at launch, each with a brief content specification; a chatbot FAQ design for the 15 most common transactional questions; a search optimisation approach (how employees find answers without knowing what to call things); a launch communication plan; and a content maintenance process including ownership, review schedule, and a process for flagging outdated content. Include the full content specifications for 3 of the top 10 content items.","tags":["hr-technology","hr-ops","communications"],"author":"AINOW","created":"2024-02-15T15:30:00Z","featured":false},

    {"id":"hr-68","title":"HR Process Automation Assessment","prompt":"You are an HR Operations lead. Conduct a systematic HR process automation opportunity assessment for a 400-person company with a 5-person HR team that spends approximately 60% of its time on administrative and transactional tasks. Write the assessment framework and results. The framework should cover: a process inventory methodology to map all HR processes and estimate the time spent on each; an automation suitability scoring model evaluating each process on rule-based repeatability, volume, error risk, and strategic value; a categorisation of processes into Automate Now (rule-based, high volume, low exception rate), Automate with Human Review (rule-based but consequential), Redesign Before Automating (broken processes not worth automating as-is), and Keep Human (complex judgment required); tool recommendations for specific automation categories (HRIS workflow automation, RPA, chatbots, e-signature, and document generation); a business case template for calculating ROI of automation (hours saved x cost per hour vs implementation cost); and a 12-month roadmap prioritising the top 8 automation opportunities. Include the full process scoring matrix with 20 sample HR processes evaluated.","tags":["hr-technology","hr-ops","efficiency"],"author":"AINOW","created":"2024-02-15T15:35:00Z","featured":false},

    {"id":"hr-69","title":"Organisational Redesign Process Guide","prompt":"You are an Organisational Effectiveness Director. A 700-person professional services company is undergoing a significant reorganisation: moving from a functional structure (siloed by practice area) to a client-sector matrix structure, to improve cross-functional collaboration and reduce duplicated effort. The CEO has announced the redesign will take 6 months. Write a complete organisational redesign process guide. Include: a design principles process for establishing the criteria the new structure must meet before drawing org charts; a current state analysis methodology (span of control analysis, decision rights mapping, cost allocation review, and culture impact assessment); a future state options generation process (at least 3 structural options) and a decision framework for selecting among them; a detailed implementation plan covering role definition, reporting line changes, transition communications, and the critical first 90 days; a people impact assessment framework; a change risk assessment; and a stabilisation phase plan for months 6–12. Include the design principles facilitation guide for the executive team session.","tags":["org-design","change-management","strategy"],"author":"AINOW","created":"2024-02-15T15:40:00Z","featured":false},

    {"id":"hr-70","title":"Change Management Framework for HR Programs","prompt":"You are a Change Management specialist. Write a practical change management framework for HR leaders who regularly implement new programs and policies (performance review redesign, new HRIS, compensation transparency, etc.) and frequently encounter resistance, low adoption, and implementation failures. The framework should be based on evidence-based change models (ADKAR or Kotter) and adapted for the HR context. Include: a change readiness assessment template to use before any significant program launch; a stakeholder mapping and influence strategy tool; a communication planning template with audience segmentation, message architecture, and channel selection; a resistance identification and management guide (types of resistance, root causes, and response strategies); a manager activation plan for changes that require manager involvement to succeed; a training needs analysis for change-driven learning requirements; a feedback loop design for capturing implementation issues in real time; and a change saturation assessment for organisations that have multiple simultaneous HR changes. Include a worked example applying the framework to a new performance management system rollout.","tags":["change-management","hr-ops","strategy"],"author":"AINOW","created":"2024-02-15T15:45:00Z","featured":false},

    {"id":"hr-71","title":"Merger Integration People Workstream Plan","prompt":"You are an HR Director leading the People workstream of a merger between two mid-size companies (acquirer: 600 people, acquired: 250 people, combined entity target: 750 people after 100 position eliminations due to duplication). Write a complete People Workstream integration plan covering the first 12 months post-close. Include: a Day 1 readiness checklist covering communications, employment contract review, payroll continuity, benefits eligibility, and IT access; a cultural integration assessment process for understanding the cultural differences between the two companies and the risks of imposing one culture on the other; an organisational design process for the combined entity including how to handle duplicate roles fairly; a compensation and benefits harmonisation plan with a timeline (harmonising two different pay structures and benefits packages is typically a 12-month process); a talent retention strategy for key employees at the acquired company; a communication strategy addressing the most common employee fears in a merger; and a 90-day integration health check framework. Include the Day 1 all-employee communication from the Combined CEO.","tags":["change-management","org-design","strategy"],"author":"AINOW","created":"2024-02-15T15:50:00Z","featured":true},

    {"id":"hr-72","title":"Span of Control Analysis Guide","prompt":"You are an Organisational Design specialist. Write a complete span of control analysis guide for an HR team conducting an organisational health review for a 600-person company that has grown rapidly through acquisition and now has 120 managers, some with 2 direct reports and some with 22. The guide should cover: what span of control is and why it matters for cost, communication speed, and manager effectiveness; the factors that influence optimal span (role complexity, work independence, manager experience, team maturity, and geographic dispersion) and a scoring model for each factor; a span of control benchmarking approach with typical ranges for different function types (e.g. operational vs knowledge work); a data collection methodology for auditing current spans across the organisation; a visualisation approach for presenting span data to leadership; a decision framework for identifying which spans need adjustment; a transition process for changing spans (adding, removing, or reassigning direct reports); and the people implications of span changes. Include the span of control scoring model and a sample visualisation description for an org-level span map.","tags":["org-design","hr-analytics","strategy"],"author":"AINOW","created":"2024-02-15T15:55:00Z","featured":false},

    {"id":"hr-73","title":"Return to Office Change Management Plan","prompt":"You are a Change Management lead. A 450-person technology company that has been fully remote for 3 years is mandating a 3-day-per-week in-office requirement for all employees, effective in 90 days. Leadership anticipates significant resistance: 35% of employees relocated during the remote period and live more than 90 minutes from the office, and the most recent engagement survey showed that flexibility is the number-one reason people stay. Write a complete change management plan for this transition. Include: a risk assessment quantifying the retention risk, covering which employee segments are most at risk; a policy design recommendation (should exceptions be allowed, and on what grounds?); a manager briefing guide and FAQ; an all-company communication sequence (announcement, FAQ, follow-up, and 30-day check-in); a process for handling accommodation requests; a strategy for making the in-office experience worth the commute; and a 90-day sentiment monitoring plan. Include a recommendation letter to the CEO with a frank assessment of the risks and a suggested middle-ground policy if full enforcement is likely to cause significant attrition.","tags":["change-management","employee-relations","strategy"],"author":"AINOW","created":"2024-02-15T16:00:00Z","featured":false},

    {"id":"hr-74","title":"Job Architecture Design","prompt":"You are a Compensation and Organisational Design specialist. Design a comprehensive job architecture for a 500-person technology company that currently has 312 different job titles, no standardised levels, and inconsistent career pathing. The architecture should provide the foundation for compensation bands, career paths, and workforce planning. Include: a job family structure (a recommended set of 8–12 job families for a technology company, with a definition of each); a level framework with 6–8 levels spanning from entry to C-suite, with level definitions for each; a job grade system mapping levels to grades; a titling convention methodology to generate consistent job titles across functions; a levelling assessment framework so managers can accurately place roles in the architecture; a process for converting from the current 312 titles to the new architecture including how to handle employees who feel their title has been downgraded; and the link from architecture to compensation bands. Include the full level framework with level descriptions for the Individual Contributor track and the Management track.","tags":["org-design","compensation","hr-ops"],"author":"AINOW","created":"2024-02-15T16:05:00Z","featured":false},

    {"id":"hr-75","title":"Agile HR Transformation Guide","prompt":"You are an HR transformation consultant. Write a practical guide for transforming an HR function from a traditional, process-heavy model to a more agile, product-oriented operating model in a 600-person technology company whose engineering teams have been working in agile for years and find the HR function slow and bureaucratic. The guide should cover: what agile HR means in practice (not just adopting sprints, but a mindset shift toward continuous iteration, customer-centricity, and cross-functional squads); a diagnostic for assessing the current HR operating model against agile principles; a phased transformation roadmap across 18 months; how to organise the HR team into agile squads (suggested squad structures and how they differ from the traditional HR silo model); how to apply product thinking to HR programs (defining employee personas, user stories, and minimum viable products for HR initiatives); how to measure HR team velocity and quality; and the change management challenges specific to transforming HR itself (not just HR driving change elsewhere). Include a sample user story for an HR product — the performance management system — written from the employee's perspective.","tags":["hr-ops","change-management","strategy"],"author":"AINOW","created":"2024-02-15T16:10:00Z","featured":false},

    {"id":"hr-76","title":"HR Business Partner Effectiveness Model","prompt":"You are the Chief People Officer redesigning the HR Business Partner model at a 700-person company where HRBPs spend 70% of their time on transactional HR queries, employee relations cases, and reporting — leaving only 30% for strategic partnering. The leadership team does not find HR a strategic partner. Write a complete HRBP Effectiveness Model and redesign plan. Include: a diagnosis framework for assessing where HRBP time is currently spent vs where it should be spent; a capability model for strategic HRBPs covering business acumen, data fluency, organisation diagnosis, influence without authority, and coaching; a transition plan for migrating transactional work to HR Shared Services and self-service, freeing HRBP capacity; a relationship management framework for how HRBPs should engage with their business leaders (regular cadence, preparation, and value-add deliverables); a HRBP performance evaluation framework aligned to business outcomes not just HR activities; and a capability development plan for current HRBPs who need to upskill. Include the HRBP time allocation target model (what percentages of time should go where) and the HRBP business review agenda template.","tags":["hr-ops","strategy","hr-business-partner"],"author":"AINOW","created":"2024-02-15T16:15:00Z","featured":false},

    {"id":"hr-77","title":"HR Operating Model for a Global Company","prompt":"You are an HR Director designing the HR operating model for a technology company that has grown from 200 to 900 employees across 12 countries in the past 3 years. The current HR team of 18 is overwhelmed, inconsistent across geographies, and is structured entirely as generalists with no specialisation. Write a complete HR operating model design for the current scale. Include: a recommended HR organisational structure with a Centres of Excellence (COE) model, HR Business Partners, and an HR Shared Services function — with headcount recommendations for each and role descriptions for the 5 most critical roles; a service delivery model showing which HR activities are handled by COEs, HRBPs, and Shared Services respectively; a governance model for how global policy is set and locally adapted; a technology architecture that supports the operating model; a process for managing employment law compliance across 12 different jurisdictions; and a transition plan from the current structure to the target model. Include an org chart description for the target state HR function and the critical role profiles for the Head of Talent Acquisition, Head of People Operations, and HR Business Partner.","tags":["hr-ops","org-design","global-hr"],"author":"AINOW","created":"2024-02-15T16:20:00Z","featured":false},

    {"id":"hr-78","title":"Headcount Planning Process Design","prompt":"You are a Workforce Planning lead. Design a quarterly headcount planning process for a 500-person company that currently approves new hires on an ad hoc basis, resulting in budget overruns, hiring backlogs, and misalignment between business strategy and workforce investment. The process should integrate HR, Finance, and business leaders. Include: a planning calendar showing when each step happens in the quarter; a headcount request form template capturing business case, role justification, start date, compensation range, and backfill vs new role classification; a calibration process between HR and Finance to reconcile headcount requests with budget; a quarterly headcount review meeting agenda and materials; a rolling 12-month headcount forecast template; a process for urgent out-of-cycle hires (when is this appropriate and how is it approved?); a workforce mix analysis framework (FTE vs contractor vs outsourced); and a reporting template for presenting headcount status to the executive team. Include the headcount request form and the executive headcount reporting template.","tags":["workforce-planning","hr-ops","finance"],"author":"AINOW","created":"2024-02-15T16:25:00Z","featured":false},

    {"id":"hr-79","title":"Global Mobility and Expatriate Management","prompt":"You are a Global Mobility Manager at a 600-person company planning to move 12 employees from the US headquarters to newly opened offices in the UK, Germany, and Singapore over the next 18 months. Write a complete expatriate management framework. Cover: the employment structure decision (remain employed by the home entity vs transfer to the host entity vs split payroll) and the tax and legal implications of each; a cost-of-living and cost-of-assignment calculation methodology; a total expatriate package design including assignment premium, housing allowance, school fees policy, home leave flights, and tax equalisation; a tax and social security compliance framework across all 3 host countries; a pre-departure preparation checklist including immigration (visa types and timelines for each country), cultural orientation, home property management, and banking; a spouse/partner employment support policy; a repatriation policy covering what the returning employee's role will be; and an emergency assistance protocol. Include a sample assignment letter of understanding for the UK assignment.","tags":["global-hr","compensation","compliance"],"author":"AINOW","created":"2024-02-15T16:30:00Z","featured":false},

    {"id":"hr-80","title":"TUPE and Business Transfer HR Guide","prompt":"You are an employment law-informed HR Director in the UK. A 450-person company is acquiring a 120-person outsourced facilities management business, meaning 120 employees will transfer under the Transfer of Undertakings (Protection of Employment) Regulations 2006 (TUPE). Write a complete TUPE compliance guide for the HR team. Include: a plain-English explanation of what TUPE means and what it protects; the information and consultation obligations on both the transferor and transferee, including the required timing, content, and form of the employee liability information; the ETO (Economic, Technical, or Organisational) reason defence and when it applies; how to handle employees who refuse to transfer; the process for harmonising terms and conditions post-transfer and the legal constraints on doing so; a communication plan for the transferring employees that is legally compliant and human; a 100-day integration plan for the transferred employees; and a checklist of actions for the 90 days before, on, and 30 days after the transfer date. Include the employee notification letter template.","tags":["legal","employee-relations","global-hr"],"author":"AINOW","created":"2024-02-15T16:35:00Z","featured":false},

    {"id":"hr-81","title":"Mental Health First Aid Program Design","prompt":"You are a Wellbeing Programs Manager. Design a workplace Mental Health First Aid (MHFA) program for a 500-person company where the most recent engagement survey showed that 48% of employees are concerned about their own mental health, 71% say they would not feel comfortable disclosing a mental health challenge to their manager, and the EAP utilisation rate is 4% (industry average 6–8%). The program should include: a business case with cost estimates of untreated mental health on productivity, absenteeism, and turnover; a trained Mental Health First Aider selection process (how many to train, who should be eligible, how they are identified to employees); the MHFA certification process — partner with Mental Health First Aid England or MHFA USA, 2-day certification, 3-year renewal; a role scope definition for MHFAiders (what they do and critically what they do not do — they are not therapists); a launch and awareness campaign; a manager training module (3 hours) on recognising signs of mental distress and having a supportive conversation; and an annual program health check. Include the manager mental health conversation guide.","tags":["wellbeing","learning-development","employee-relations"],"author":"AINOW","created":"2024-02-15T16:40:00Z","featured":false},

    {"id":"hr-82","title":"Hybrid Work Equity Framework","prompt":"You are an HR Director. Eighteen months after mandating a 2-day in-office hybrid model, internal data at a 400-person company shows that employees who come into the office more than the required minimum receive 23% more informal feedback from managers, are nominated for high-visibility projects at a rate 1.8x higher than primarily remote employees, and receive promotions at a 31% higher rate than employees who work mostly remotely. Write a Hybrid Work Equity Framework to identify and address proximity bias. Include: a diagnostic section explaining the research on proximity bias and its career impact; a data analysis framework for auditing promotion, project assignment, and informal recognition data by in-office vs remote frequency; a manager accountability framework (what managers are expected to do to ensure equitable access to opportunity regardless of work location); specific practices for equitable meeting facilitation, project assignment, mentoring, and performance evaluation in hybrid teams; a leadership modelling campaign (what senior leaders should visibly do differently); and a policy recommendation on whether the current hybrid model should be adjusted. Include the manager equity checklist for hybrid teams.","tags":["dei","remote-work","management"],"author":"AINOW","created":"2024-02-15T16:45:00Z","featured":true},

    {"id":"hr-83","title":"Employee Listening Strategy","prompt":"You are a People Insights lead. The company's current employee listening approach consists of one annual engagement survey and an informal 'open door' policy. 43% of employees say they do not believe the company acts on feedback. Design a comprehensive Employee Listening Strategy for a 550-person company. The strategy should describe a multi-channel, multi-cadence listening system that includes: an annual engagement survey (redesigned — purpose, question design, administration, and reporting); a quarterly pulse survey (5 questions, specific focus areas that rotate quarterly, real-time manager-level dashboards); new hire check-ins (30-day and 90-day structured conversations or surveys); stay interviews (for employees with 1–3 years tenure, manager-conducted, quarterly); exit interviews (redesigned to focus on actionable data); always-on feedback channels; and leadership listening forums (quarterly town halls, skip-level conversations, and CEO listening lunches). For each channel, specify cadence, owner, question design, how data is analysed, and critically, how insights are closed-looped back to employees. Include a 'You said, we did' communication template.","tags":["culture","hr-analytics","employee-experience"],"author":"AINOW","created":"2024-02-15T16:50:00Z","featured":false},

    {"id":"hr-84","title":"Talent Intelligence and Market Mapping","prompt":"You are a senior Talent Intelligence specialist. Write a complete talent market mapping methodology guide for a talent acquisition team at a 500-person company that wants to build proactive talent pipelines for 5 critical technical roles 6–12 months before they need to hire. The guide should cover: what talent intelligence is and how it differs from reactive sourcing; a market mapping methodology covering competitor talent pool size estimation (how to use LinkedIn and other tools to estimate how many people with a specific skill set exist in a given geography); a competitive intelligence framework for understanding what competitors pay, how long they retain talent, and where they source from; a passive talent engagement strategy for building a relationship with identified candidates before a role opens; a talent community design (how to build and nurture a talent community, what content to share, and how to keep candidates warm over 6–12 months); a market insights reporting format for presenting talent market data to hiring managers; and a data ethics framework for talent intelligence (what data can be collected and stored and for how long). Include a worked example mapping the market for ML Engineers in the UK.","tags":["talent-acquisition","hr-analytics","strategy"],"author":"AINOW","created":"2024-02-15T16:55:00Z","featured":false},

    {"id":"hr-85","title":"HR Compliance Calendar and Audit Framework","prompt":"You are an HR Compliance Manager at a 500-person US company operating in California, New York, Texas, and Washington. Write a complete HR compliance calendar and audit framework for the calendar year. The calendar should cover all mandatory compliance activities by month including: Federal compliance deadlines (EEO-1 filing, OSHA 300A posting, ACA reporting, Form W-2 issuance, 401k non-discrimination testing, and I-9 audit); California-specific requirements (pay data reporting, mandatory training deadlines, minimum wage updates); a quarterly HR policy review process; an annual employee handbook review; an annual pay equity audit; an annual benefits audit (including non-discrimination testing for FSAs and HRAs); and a manager compliance training refresh. For each item include: the deadline, the responsible owner, the consequence of non-compliance, and a preparation lead time. Also design an annual HR compliance audit checklist covering 50 compliance checkpoints across employment law, safety, payroll, and data privacy. Include the full Q1 compliance calendar with specific dates.","tags":["compliance","hr-ops","legal"],"author":"AINOW","created":"2024-02-15T17:00:00Z","featured":false},

    {"id":"hr-86","title":"Psychological Safety for Senior Leadership Teams","prompt":"You are an executive coach and organisational psychologist. A Chief People Officer has approached you with a concern: the company's senior leadership team of 10 people (C-suite and VPs) scored 3.1 out of 5 on psychological safety in a recent 360 assessment. Meeting observations show that three of the most senior leaders dominate discussions, dissenting views are rarely voiced until after meetings, and one VP was publicly criticised by the CEO in a recent all-hands. Write a 6-month intervention plan to build psychological safety within the senior leadership team. Include: a root cause diagnostic approach (leadership interviews, team observation, meeting analysis); a structured feedback process for the CEO on their own behaviours and their impact on team safety; a team development workshop series (3 workshops, content outlines for each); new meeting norms and decision-making protocols to codify safe dialogue; an individual coaching plan template for the 3 dominant leaders; and a measurement approach. Write the CEO feedback conversation guide in full — this is the most critical and delicate intervention.","tags":["leadership","culture","coaching"],"author":"AINOW","created":"2024-02-15T17:05:00Z","featured":false},

    {"id":"hr-87","title":"HR During a Crisis: Business Continuity Plan","prompt":"You are a Chief People Officer. Write an HR Business Continuity Plan for a 600-person company covering the three most common and disruptive HR crises: a sudden senior executive departure (CFO resigns with 2 weeks' notice), a significant data breach exposing employee personal data, and a natural disaster or severe weather event affecting the primary office location. For each scenario include: a 24-hour response checklist (who calls whom, what decisions need to be made immediately, and what can wait); a communication protocol specifying who communicates, to whom, through what channel, and in what timeframe; HR's specific responsibilities vs legal, communications, and IT; the key decisions HR must make in the first 72 hours; a 30-day stabilisation plan; and lessons learned documentation. Also write the general crisis HR playbook cover page including the HR crisis team structure, contact list template, and decision authority matrix. Include the full 24-hour response checklist for the data breach scenario.","tags":["hr-ops","crisis","compliance"],"author":"AINOW","created":"2024-02-15T17:10:00Z","featured":false},

    {"id":"hr-88","title":"People Manager Competency Framework","prompt":"You are a Talent Management specialist. Build a People Manager Competency Framework for a 500-person technology company to be used as the foundation for manager selection, development, performance evaluation, and promotion decisions. The framework should include: a philosophy statement on what the company believes great management means; 8 core management competencies with a one-sentence definition of each; for each competency, a full behavioural indicator table showing what the competency looks like at three levels — Developing, Proficient, and Exemplary — with 3 specific observable behaviours at each level; a competency prioritisation guide indicating which competencies are most critical at first-time manager level vs senior manager level vs director level; a self-assessment tool for managers to evaluate themselves against the framework; a manager selection interview question bank with 2 behavioural questions per competency; and a development resource guide linking each competency to specific learning resources. Include the full behavioural indicator table for the competency 'Develops Others'.","tags":["management","learning-development","talent"],"author":"AINOW","created":"2024-02-15T17:15:00Z","featured":false},

    {"id":"hr-89","title":"Employer Brand Content Strategy","prompt":"You are a Talent Brand Manager. Write a 6-month employer brand content strategy for a 400-person healthcare technology company that wants to increase the quality and diversity of inbound job applications by 40% and reduce cost-per-hire by 25%. The company currently has minimal social media presence for employer branding (a LinkedIn page with 3,200 followers, rarely updated, and a Glassdoor rating of 3.6). The content strategy should cover: a brand audit of the current state across LinkedIn, Glassdoor, the careers page, and job descriptions; an employer brand platform (the core message and proof points that will run through all content); a LinkedIn content plan for 24 weeks with post types (employee story, culture moment, team spotlight, technical insight, impact story), posting frequency, and editorial guidelines; a Glassdoor response strategy for reviews (both positive and negative); a careers page rewrite brief; a job description refresh guide; an employee advocacy program to amplify reach through employee networks; and a measurement framework. Include 5 fully written sample LinkedIn posts.","tags":["employer-branding","talent-acquisition","communications"],"author":"AINOW","created":"2024-02-15T17:20:00Z","featured":false},

    {"id":"hr-90","title":"Onboarding Buddy Program Complete Guide","prompt":"You are a People Experience specialist. Design and write a complete Onboarding Buddy Program guide for a 350-person company. The buddy program pairs new hires with an experienced employee (not their manager) for their first 90 days. The guide should include: the business case for the program with data on its impact on 90-day retention and time-to-productivity; eligibility and selection criteria for buddies; a buddy nomination and matching process (including how to match for functional relevance vs social fit); a buddy training guide — a 60-minute session covering the buddy's role, what to cover in each meeting, how to support without micromanaging, and how to escalate concerns; a structured 90-day buddy conversation guide with a suggested topic and question for each week (write out weeks 1–4 in full and provide themes for weeks 5–12); a buddy recognition system; a program evaluation approach using new hire 30-day and 90-day survey data; and an FAQ for buddies. The full guide should be polished enough to hand to a buddy with no additional training.","tags":["onboarding","employee-experience","learning-development"],"author":"AINOW","created":"2024-02-15T17:25:00Z","featured":false},

    {"id":"hr-91","title":"Flexible Working Policy and Manager Guide","prompt":"You are an HR Business Partner. Draft a comprehensive flexible working policy and accompanying manager guide for a 450-person company that wants to genuinely embrace flexibility (not just offer it on paper). The policy should cover: the types of flexibility available — flexible hours (core hours model), compressed work week (4-day week pilot eligibility criteria), job sharing, part-time, and career break; the process for requesting a flexible arrangement (form, conversation with manager, decision timeline, trial period); the criteria managers should use to assess requests (role requirements, team impact, individual track record) and a requirement that all requests receive a substantive written response within 10 working days; the rights of employees to appeal a declined request; how flexible arrangements are reviewed and renewed; the equal treatment commitment (flexible workers must not face disadvantage in pay, development, or progression). The manager guide (separate from the policy) should cover: how to have a flexible working conversation; how to manage a team with varied working patterns; how to avoid proximity bias; and how to run an outcome-based performance model for flexible workers.","tags":["employee-relations","policy","management"],"author":"AINOW","created":"2024-02-15T17:30:00Z","featured":false},

    {"id":"hr-92","title":"Toxic Manager Early Warning System","prompt":"You are a People Analytics and Employee Relations specialist. Design an early warning system for identifying toxic management behaviour before it results in high turnover, formal complaints, or reputational damage. At a 600-person company, post-exit interview analysis shows that 41% of voluntary leavers cite 'my manager' as the primary reason for leaving, yet only 2 formal complaints were filed in the past 12 months — suggesting widespread underreporting. The system should include: a data signal framework identifying the quantitative signals that correlate with toxic management (team turnover rate, sick leave rate, internal transfer requests, 360 score trends, pulse survey scores, and time-to-hire data for the team); a qualitative signal guide for HRBPs based on conversation observation; a signal threshold model defining when enough signals warrant an HRBP check-in with the manager vs a formal performance conversation; an HRBP investigation-lite protocol (when signals are present but there is no formal complaint); a manager support vs manager accountability decision framework; and a closed-loop tracking system to monitor intervention outcomes. Include the data signal thresholds table.","tags":["employee-relations","hr-analytics","management"],"author":"AINOW","created":"2024-02-15T17:35:00Z","featured":true},

    {"id":"hr-93","title":"HR Metrics That Matter to the Board","prompt":"You are a Chief People Officer preparing your first quarterly People Report for the Board of Directors of a 500-person private equity-backed company. The board is financially oriented, does not care about HR jargon, and wants to understand whether the company's investment in people is generating a return. Write the full HR board report template and a narrative guide for completing it. The report should include: an executive summary in 3 bullet points; a Workforce Health section with metrics including voluntary regrettable turnover rate, time-to-fill for critical roles, and internal mobility rate, each with a trend chart and commentary; a Talent Pipeline section showing succession coverage for the top 15 critical roles; a Productivity section with revenue per FTE and cost per hire trends; a Culture and Engagement section with eNPS trend and top 2 engagement risks; a Compliance section showing any open or resolved HR legal matters; and a People Investment section showing total HR cost as a percentage of revenue and L&D spend per employee. For each metric, include the benchmark, the company's current performance, and the narrative. Write the executive summary in full.","tags":["hr-analytics","strategy","board-reporting"],"author":"AINOW","created":"2024-02-15T17:40:00Z","featured":true},

    {"id":"hr-94","title":"Neurodiversity Inclusion Program","prompt":"You are a Diversity and Inclusion specialist. Design a Neurodiversity Inclusion Program for a 500-person technology company. Research suggests that 15–20% of the workforce may be neurodivergent (including ADHD, autism, dyslexia, dyspraxia, and others) but disclosure rates in most companies are below 3%, indicating significant unmet need. The program should cover: an awareness campaign to normalise neurodiversity and increase psychological safety for disclosure; manager training (2-hour module) on understanding neurodiversity, having a disclosure conversation, and making adjustments — include the full training agenda; a reasonable adjustments fast-track process for neurodivergent employees (simpler, faster, and more confidential than the standard accommodations process); workplace design recommendations for sensory-friendly spaces; interview process accommodations for neurodivergent candidates (advance questions, extended time, alternative formats); a neurodiversity employee resource group launch guide; and a partnership with a specialist neurodiversity assessment and support provider. Include the manager training module agenda and the 5 most common adjustments for ADHD, autism, and dyslexia respectively.","tags":["dei","inclusion","disability"],"author":"AINOW","created":"2024-02-15T17:45:00Z","featured":false},

    {"id":"hr-95","title":"People Operations Playbook for Startups","prompt":"You are an experienced Head of People joining a Series A startup of 45 people as their first HR hire. The company has no HR infrastructure: no documented policies, no performance management process, compensation set by individual negotiation, and onboarding that consists of 'here is your laptop, talk to the engineers'. Write a People Operations Playbook covering what to build in your first 6 months. Prioritise ruthlessly — you are one person with no budget for consultants. Month 1–2: legal and compliance foundations (what policies and documents are legally required before anything else, and what is the fastest way to get them in place); Month 2–3: compensation foundations (how to bring consistency to a chaotic compensation landscape without a full benchmarking project); Month 3–4: performance basics (a lightweight performance framework that works at 45 people and can scale to 200); Month 4–5: hiring process (bringing consistency to an ad hoc process); Month 5–6: engagement foundation (how to take the company's first real employee engagement measurement). For each phase include: the 3 highest-priority actions, the minimum viable output, and what to deprioritise.","tags":["hr-ops","strategy","startups"],"author":"AINOW","created":"2024-02-15T17:50:00Z","featured":true},

    {"id":"hr-96","title":"Parental Leave Policy and Return-to-Work Program","prompt":"You are an HR Director who believes that how a company designs its parental leave policy and return-to-work experience is one of the single biggest signals of its values toward working parents. Design a comprehensive parental leave policy and return-to-work program for a 400-person company. The policy should cover: primary carer leave (recommend the duration, phased return option, and pay structure — full pay for the first X weeks, then enhanced statutory); secondary carer leave (recommend the duration — argue for a minimum of 8 weeks to challenge gender norms); adoption leave on equal terms to birth leave; pregnancy loss leave (including miscarriage and stillbirth); a keeping-in-touch (KIT) day framework that is genuinely optional; protection against disadvantage on return (specific commitments). The return-to-work program should include: a 12-week return-to-work ramp plan with reduced meetings and project load; a returnship option for employees who have been on leave for 12+ months; a manager guide for the return conversation; a buddy program pairing returning parents with a parent who returned in the past 18 months; and a breastfeeding support provision. Include the return-to-work ramp plan template.","tags":["policy","wellbeing","employee-relations"],"author":"AINOW","created":"2024-02-15T17:55:00Z","featured":false},

    {"id":"hr-97","title":"Compensation Review Communication Scripts","prompt":"You are an HR Business Partner coaching 12 managers who are about to deliver annual compensation review outcomes to their teams. Some employees will receive merit increases of 3–8%, some will receive 0% due to performance or budget constraints, and 4 high performers will receive out-of-cycle equity refreshes. Write a complete communication guide covering: the underlying message architecture (what managers should and should not say about budget, market data, and performance linkage); a script for delivering a strong merit increase to a high performer (with guidance on connecting the increase to their specific contributions); a script for delivering a 0% outcome to an employee who has performed adequately but below 'exceeds expectations', and how to respond to disappointment without making promises; a script for delivering a 0% outcome to an employee who is on a performance improvement plan; a script for explaining an equity refresh without revealing other employees' grants; a 'questions managers will get' FAQ covering 15 anticipated questions with model answers; and a follow-up check-in guide for 2 weeks after conversations. Write all 4 scripts in full.","tags":["compensation","communications","management"],"author":"AINOW","created":"2024-02-15T18:00:00Z","featured":false},

    {"id":"hr-98","title":"Workforce Analytics Capability Building Plan","prompt":"You are an HR Analytics Director. Build a 12-month capability development plan to upskill a team of 6 HR Generalists and HRBPs at a 550-person company in people data and analytics. The team currently has low data confidence: only 2 of the 6 can build a pivot table, none can run a regression, and HR decisions are largely made without reference to data. The plan should cover: a skills baseline assessment tool for the team; a tiered learning curriculum (Tier 1: data literacy for all HRBPs; Tier 2: intermediate analytics for designated analytics champions; Tier 3: advanced analytics for the 2 people who will specialise); specific learning resources for each tier (include names of actual courses, platforms like Coursera, DataCamp, or LinkedIn Learning, and self-paced estimated hours); a monthly 'data hour' practice session design; a set of 12 progressive hands-on analytics projects the team will complete over the year using real HR data, with increasing complexity; a data storytelling workshop design; and a measurement framework for the team's analytics maturity. Include the skills baseline assessment tool in full.","tags":["hr-analytics","learning-development","hr-ops"],"author":"AINOW","created":"2024-02-15T18:05:00Z","featured":false},

    {"id":"hr-99","title":"First 90 Days Plan for a New CHRO","prompt":"You are an experienced executive coach advising a new Chief Human Resources Officer joining a 700-person company from a competitor. The CHRO is talented but has a track record of moving too fast and announcing changes before building relationships. Write a detailed 90-day plan that balances relationship-building, listening, and early credibility-building without the CHRO over-promising or alienating the existing HR team. Month 1 (Listen and Learn): who to meet (specific stakeholder groups in a recommended sequence), what to ask in each meeting (provide a stakeholder interview guide), what to observe, what to read, and what not to do (specifically: no restructuring announcements, no policy changes, no public criticism of the previous CHRO's legacy); Month 2 (Synthesise and Align): how to synthesise findings into a current state diagnosis, how to align with the CEO on priorities before going public, and how to engage the HR team in co-creating the agenda; Month 3 (Commit and Communicate): a 90-day review meeting design for the CEO, an all-company HR strategy communication, and 3 quick wins to demonstrate momentum. Include the full stakeholder interview guide.","tags":["leadership","strategy","hr-ops"],"author":"AINOW","created":"2024-02-15T18:10:00Z","featured":true},

    {"id":"hr-100","title":"The Future of Work Strategy","prompt":"You are the Chief People Officer advising the Board of a 600-person company on a 5-year Future of Work strategy. The company is facing five simultaneous forces of change: AI automation of knowledge work is accelerating (estimated 30% of current job tasks automatable by 2028); the workforce spans four generations with fundamentally different expectations; skills are becoming obsolete faster than the company can retrain; remote and hybrid work has permanently changed social capital and collaboration patterns; and demographic changes mean the talent market for critical roles will tighten significantly. Write a Future of Work strategy covering: a horizon-scanning section analysing how each of the 5 forces will impact this specific company by 2028; a strategic workforce response for each force including specific actions, investments, and policy changes; a reskilling and workforce transition philosophy and investment commitment; a future of work principles document for how the company will make decisions about automation, skills, and ways of working; a governance model for future of work decisions; and a 12-month action plan for the most urgent items. The strategy should be honest about the hard trade-offs, not aspirational boilerplate.","tags":["future-of-work","strategy","workforce-planning"],"author":"AINOW","created":"2024-02-15T18:15:00Z","featured":true}

];
  __exports.hrPrompts = hrPrompts;
})();
